<?php
use App\Core\{DB,Security};
use App\Models\{Project,Ticket,TicketBranch,RepositoryConnection,DevelopmentEvent};
use App\Services\DevelopmentPayload;

$tbProject=Project::save(['name'=>'Branches explicites','key'=>'BL'.strtoupper(bin2hex(random_bytes(3)))]);
$tbOther=Project::save(['name'=>'Branches partagées','key'=>'BS'.strtoupper(bin2hex(random_bytes(3)))]);
$tbConnection=DB::insert('INSERT INTO connections(project_id,provider,repository,secret_cipher,webhook_cipher) VALUES(?,?,?,?,?)',[$tbProject,'github','sample/branches',Security::encrypt('test-branch-token'),Security::encrypt('test-branch-hook')]);
RepositoryConnection::attach($tbProject,$tbConnection,true);RepositoryConnection::attach($tbOther,$tbConnection);
$tbC=DB::one('SELECT * FROM connections WHERE id=?',[$tbConnection]);
$tbTicket=Ticket::create($tbProject,['title'=>'Sans clé dans le nom'],$uid);$tbSecond=Ticket::create($tbOther,['title'=>'Même dépôt autre projet'],$uid);
$tbInitialVersion=Ticket::find($tbTicket)['version'];
$tbName='feature/correction-sitemap';$tbEvent=DevelopmentPayload::object('github','branch',['name'=>$tbName,'commit'=>['sha'=>str_repeat('a',40)]],$tbC['repository']);
$tbPast=DevelopmentEvent::save($tbC,DevelopmentPayload::object('github','commit',['sha'=>str_repeat('9',40),'message'=>'Déjà reçu sans référence'],$tbC['repository'],false,$tbName));
$tbLink=TicketBranch::link($tbTicket,$tbC,$tbEvent,$uid);$tbAgain=TicketBranch::link($tbTicket,$tbC,$tbEvent,$uid);
check((int)DB::one('SELECT COUNT(*) n FROM development_event_tickets WHERE event_id=? AND ticket_id=?',[$tbPast,$tbTicket])['n']===1,'liaison reprend les observations déjà reçues pour cette branche');
check($tbLink===$tbAgain && count(TicketBranch::all($tbTicket))===1,'liaison de branche idempotente sans clé du ticket');
check(Ticket::find($tbTicket)['version']===$tbInitialVersion,'lier une branche ne modifie pas les champs du ticket');
check(TicketBranch::providersForTickets([$tbTicket,$tbUnlinked=Ticket::create($tbProject,['title'=>'Sans branche'],$uid)])===[$tbTicket=>['github']],'fournisseur lié disponible sans marquer les autres tickets du projet');
$tbEventId=DB::one('SELECT id FROM development_events WHERE connection_id=? AND external_key=?',[$tbConnection,$tbEvent['external_key']])['id'];
check((int)DB::one('SELECT COUNT(*) n FROM development_event_tickets WHERE event_id=? AND ticket_id=?',[$tbEventId,$tbTicket])['n']===1,'branche vérifiée associée immédiatement');
$tbEvent['commit_sha']=str_repeat('b',40);DevelopmentEvent::save($tbC,$tbEvent,true);
check((int)DB::one('SELECT COUNT(*) n FROM development_event_tickets WHERE event_id=? AND ticket_id=?',[$tbEventId,$tbTicket])['n']===1,'webhook ou synchronisation conserve le lien manuel');
$tbCommit=DevelopmentPayload::object('github','commit',['sha'=>str_repeat('c',40),'commit'=>['message'=>'Correction sans référence']],$tbC['repository'],true,$tbName);
$tbCommitId=DevelopmentEvent::save($tbC,$tbCommit,true);
check((int)DB::one('SELECT COUNT(*) n FROM development_event_tickets WHERE event_id=? AND ticket_id=?',[$tbCommitId,$tbTicket])['n']===1,'commit poussé sur la branche manuelle associé sans clé');
$tbPR=['number'=>7,'title'=>'Correction sitemap','head'=>['ref'=>$tbName,'sha'=>str_repeat('d',40),'repo'=>['full_name'=>'sample/branches']],'state'=>'open'];
$tbPrId=DevelopmentEvent::save($tbC,DevelopmentPayload::object('github','pull_request',$tbPR,$tbC['repository']));
check((int)DB::one('SELECT COUNT(*) n FROM development_event_tickets WHERE event_id=? AND ticket_id=?',[$tbPrId,$tbTicket])['n']===1,'pull request du dépôt source et de la branche liée reconnue');
$tbPR['number']=8;$tbPR['head']['repo']['full_name']='fork/other';$tbPR['head']['sha']=str_repeat('e',40);
$tbForeign=DevelopmentEvent::save($tbC,DevelopmentPayload::object('github','pull_request',$tbPR,$tbC['repository']));
check((int)DB::one('SELECT COUNT(*) n FROM development_event_tickets WHERE event_id=?',[$tbForeign])['n']===0,'branche homonyme d’un fork sans même commit non attribuée au lien manuel');
$tbCase=DevelopmentEvent::save($tbC,DevelopmentPayload::object('github','branch',['name'=>strtoupper($tbName)],$tbC['repository']));
check((int)DB::one('SELECT COUNT(*) n FROM development_event_tickets WHERE event_id=?',[$tbCase])['n']===0,'identité de branche sensible à la casse');
$tbSecondLink=TicketBranch::link($tbSecond,$tbC,$tbEvent,$uid);
check((int)DB::one('SELECT COUNT(*) n FROM development_event_tickets WHERE event_id=?',[$tbEventId])['n']===2,'même branche explicitement liée à deux projets partageant le dépôt');
rejects(fn()=>TicketBranch::unlink($tbTicket,$tbSecondLink),'lien d’un autre ticket non retirable');
TicketBranch::unlink($tbTicket,$tbLink);
check(count(TicketBranch::all($tbTicket))===0 && (int)DB::one('SELECT COUNT(*) n FROM development_event_tickets WHERE event_id=? AND ticket_id=?',[$tbEventId,$tbTicket])['n']===0,'retrait manuel réévalue la branche sans supprimer les observations');
check((int)DB::one('SELECT COUNT(*) n FROM development_event_tickets WHERE event_id=? AND ticket_id=?',[$tbCommitId,$tbTicket])['n']===1,'observations de commits déjà reçues conservées après retrait');
$tbAuto=DevelopmentPayload::object('github','branch',['name'=>'feature/'.Ticket::find($tbTicket)['key'].'-auto'],$tbC['repository']);$tbAutoLink=TicketBranch::link($tbTicket,$tbC,$tbAuto,$uid);TicketBranch::unlink($tbTicket,$tbAutoLink);
$tbAutoId=DB::one('SELECT id FROM development_events WHERE connection_id=? AND external_key=?',[$tbConnection,$tbAuto['external_key']])['id'];
check((int)DB::one('SELECT COUNT(*) n FROM development_event_tickets WHERE event_id=? AND ticket_id=?',[$tbAutoId,$tbTicket])['n']===1,'retrait manuel conserve le rapprochement automatique par clé');
check(TicketBranch::providersForTickets([$tbTicket])===[$tbTicket=>['github']],'branche automatique conserve son indicateur après retrait manuel');
$tbBBConnection=DB::insert('INSERT INTO connections(project_id,provider,repository,secret_cipher,webhook_cipher) VALUES(?,?,?,?,?)',[$tbProject,'bitbucket','sample/bb',Security::encrypt('test-token'),Security::encrypt('test-hook')]);RepositoryConnection::attach($tbProject,$tbBBConnection);$tbBBC=DB::one('SELECT * FROM connections WHERE id=?',[$tbBBConnection]);$tbBBEvent=DevelopmentPayload::object('bitbucket','branch',['name'=>'feature/bb'],$tbBBC['repository']);$tbBBLink=TicketBranch::link($tbTicket,$tbBBC,$tbBBEvent,$uid);
check(TicketBranch::providersForTickets([$tbTicket])===[$tbTicket=>['bitbucket','github']],'deux fournisseurs dédupliqués quand plusieurs branches sont liées');
RepositoryConnection::detach($tbProject,$tbBBConnection);check(TicketBranch::providersForTickets([$tbTicket])===[$tbTicket=>['github']],'dépôt détaché ne produit plus de pictogramme');
$tbUnrelated=Ticket::create(Project::save(['name'=>'Sans dépôt','key'=>'BU'.strtoupper(bin2hex(random_bytes(3)))]),['title'=>'Hors projet Git'],$uid);
rejects(fn()=>TicketBranch::link($tbUnrelated,$tbC,$tbEvent,$uid),'dépôt étranger au projet du ticket refusé');
foreach(['../main','feature/../main','https://example.com/branch','refs/heads/main','main?token=x','bad branch','main.lock','feature/.hidden','feature//branch'] as $invalidBranch) rejects(fn()=>DevelopmentPayload::branchName($invalidBranch),'nom de branche mal formé refusé');
check(DevelopmentPayload::branchName('feature/correction-écran')==='feature/correction-écran','nom de branche Unicode préservé');
